# Style rules table: (Area, Rule, Do, Don't, Source key)
STYLE_RULES = [
 ("Voice","Address the player directly in the active voice","Pay $1 to gain 2 resources.","The player pays $1 to gain 2 resources.",'sm_great'),
 ("Voice","Use passive voice only for universal prohibitions","Mountain tiles cannot be removed from the map.","Players may not remove mountain tiles from the map.",'curby'),
 ("Person","Pick 2nd or 3rd person and stay consistent within a section","Each player reveals 1 card from their hand.","Mixing 'you move 3 pieces' and 'the player may move fewer'.",'curby'),
 ("Pronouns","Singular they; 'that player' when 'they' is ambiguous","If a player has no Scientists, that player may not research Technologies.","he / she / (s)he / s/he / he or she / him or her",'curby'),
 ("Modals","may = optional; may not = forbidden; cannot = impossible; must = compelled","If the active player cannot play a card, they must draw a card instead.","Using 'should' anywhere in rules text.",'curby'),
 ("Verbs","gain (unlimited supply) vs take (limited supply or from a player) vs give","At the end of each round, gain $5.","Using 'take' for something from the general supply.",'sm_style'),
 ("Conditions","Trigger/condition first, effect second","If you roll a 5 or higher, draw a card.","Draw a card if you roll a 5 or higher.",'curby'),
 ("Sentences","One action per sentence; the one-breath test","Choose one area of the Spaceship. In that area, add damage tokens equal to...","A single sentence with a parenthetical list plus a calculation.",'entro'),
 ("Time words","when (once/predictable) / whenever (repeatable) / if (may never happen) / at (point in time)","Whenever a player draws a card, ...","Using 'when' for something that may never occur.",'curby'),
 ("Quantifiers","each (individually) vs every / all (as a group)","Each card is scored according to its Infamy stat.","'Every card scores' when each scores separately.",'curby'),
 ("Comparatives","less for singular nouns, fewer for plural; greater/less than for numbers, higher/lower for dice","If you roll a 4 or higher...","Mixing 'greater than' and 'higher' for the same comparison type.",'curby'),
 ("Hierarchy","turn < round < act/season; phases and steps subdivide","Each player's turn consists of a Draw Phase, an Auction Phase and a Building Phase.","Using 'phase' at two different levels in the same game.",'curby'),
 ("Orientation","Hyphenate face-up / face-down consistently","Shuffle the cards into a face-down deck.","'Flip the top card of each deck face down under it' (ambiguous).",'bp84240'),
 ("Dice","One die type: 'a die'. Multiple sizes: 4d12 notation. Consider 'dice' for both numbers","Roll 4d12 and place each die on a different runway.","Alternating die/dice unpredictably within one book.",'curby'),
 ("Capitalisation","Capitalise only specific in-game components, actions and values","Gain 5 Gold from the central supply.","Capitalising Every Important-Looking Noun.",'curby'),
 ("Emphasis","Bold = keywords/headings. Italic = examples, captions, flavour. No underline. No long all-caps","Bold the keyword where it is first defined.","Underlined rules text; ALL CAPS paragraphs.",'curby'),
 ("Numbers","Digits for game quantities; spell out flavour numbers and sentence-initial numbers","Two dice may be placed on each territory.","'2 dice may be placed...' at the start of a sentence.",'sm_style'),
 ("Lists","Numbered = sequence. Bulleted = unordered options. Periods only on full sentences","1. Shuffle the deck. 2. Deal 5 cards to each player.","Numbered labels on a diagram (readers misread them as quantities).",'curby'),
 ("Punctuation","Serial (Oxford) comma; one space after a period; double quotes","Farmers, Merchants, and Tailors","Two spaces after a period.",'sm_style'),
 ("Parentheses","Short clarifications only — never new rules","Each player may deploy two Infantry Units (but not other types of units).","Parenthetical that introduces a rule found nowhere else.",'curby'),
 ("Abbreviations","Expand acronyms on first use in the rulebook (and optionally per section)","Energy Production Rate (EPR)","Multiple visually-similar acronyms: CWC vs CWL.",'curby'),
 ("References","Cite the target of any cross-reference","see Connections, p. 34","'See above' / 'as previously mentioned'.",'curby'),
 ("Flags","Treat 'exception', 'remember' and 'should' as design smells","Remove or redesign the exception.","Shipping a rule whose only home is an exception clause.",'sm_style'),
 ("Naming","A 'mat' belongs to a player; a 'board' is shared","Place your workers on your player mat.","Calling the shared board a mat, or vice versa.",'sm_style'),
 ("Keywords","Choose names that start with different letters, especially for sibling headings","Dockyards / Assembly","Shipyards / Shipbuilding as sibling headings.",'curby'),
 ("Register","Delete filler and condescension","The victory condition is to destroy all other castles.","'The victory condition is simply to destroy...'",'t1552162'),
]

# Pre-print checklist: (Phase, Item, Why)
CHECKLIST = [
 ("1. Content completeness","Every component in the box appears in the illustrated component list, with the correct count","Count errors are the most common shipped defect (Obsession)"),
 ("1. Content completeness","Every rule printed on a card, board, mat or player aid also exists in the rulebook","Rules that live only on a component vanish when the component does (Mage Knight, Triplock)"),
 ("1. Content completeness","Setup is fully specified for every supported player count","Player-count deltas are the most re-looked-up fact in most games"),
 ("1. Content completeness","Tie-breakers exist for every 'the most / the least / first place' rule","Superlatives are the classic hole-generator"),
 ("1. Content completeness","Solo / cooperative / variant modes have their own complete setup and end conditions","Imperium shipped with a missing solo-bot rule"),
 ("1. Content completeness","End-game trigger AND end-of-game sequence are both stated (does the round finish?)","'Finish the round' is assumed far more often than it is written"),
 ("2. Structure","Goal / win condition appears before the detailed rules","Readers need a purpose to attach rules to"),
 ("2. Structure","No term is used before it is defined","The single most-cited reader irritation"),
 ("2. Structure","Every forward reference cites its target section and page","Uncited forward references force blind page-flipping"),
 ("2. Structure","Exceptions and edge cases sit beside their rule or in a clearly marked section, not inline in the core flow","Exceptions in the main flow make the core unlearnable"),
 ("2. Structure","Each rule sits under the heading a confused player would actually reach for","Organisation is a retrieval problem, not only a teaching one"),
 ("2. Structure","One linear read is sufficient to understand the game","Ryan Migalla's quality metric"),
 ("3. Language","One concept = one term, everywhere, including cards and marketing copy","Synonyms force readers to hunt for a difference that does not exist"),
 ("3. Language","Effects that behave identically are worded identically (templating)","Consistent templating lets players learn a pattern once"),
 ("3. Language","Conditions precede effects in every conditional rule","Reduces misplays and enables skimming"),
 ("3. Language","No sentence fails the one-breath test","Long sentences are the main source of parse failure"),
 ("3. Language","'should' removed; 'exception' and 'remember' reviewed as design smells","Stonemaier's editorial pass"),
 ("3. Language","Repeated sets always listed in the same canonical order","Silent, cumulative cognitive load"),
 ("4. Examples & visuals","Every example covers at least one non-obvious case","Obvious examples are wasted print"),
 ("4. Examples & visuals","No rule appears only inside an example, caption or parenthetical","Paul Grogan's red flag"),
 ("4. Examples & visuals","Examples make clear which details are arbitrary","Readers infer unintended rules from examples"),
 ("4. Examples & visuals","There is a labelled setup diagram of the initial table state","Lets readers verify their setup visually"),
 ("4. Examples & visuals","Information-dense components have an anatomy diagram","Converts a component into shared vocabulary"),
 ("5. Reference apparatus","Table of contents present (and an index if the book exceeds ~12 pages)","TOC and index are different tools"),
 ("5. Reference apparatus","Icon key exists in exactly one place and is easy to find","Icon soup without a key is a top complaint"),
 ("5. Reference apparatus","Back cover carries turn flow, icon key and/or setup summary","The most valuable page in the book"),
 ("5. Reference apparatus","A short 'commonly missed rules' list exists","Highest value per word available"),
 ("5. Reference apparatus","Rulebook carries a version number and date","Enables errata and living rules"),
 ("6. Typography & print","Body text >= 10pt (12pt preferred); test the smallest text in dim light","10pt is the stated floor at Stonemaier; accessibility guidance says 12pt"),
 ("6. Typography & print","Contrast >= 4.5:1 for body text; page still readable in greyscale","WCAG-derived target"),
 ("6. Typography & print","No rules text over art, texture or dark backgrounds","Recurring cause of games being shelved"),
 ("6. Typography & print","No colour-only coding anywhere; every distinction is double-coded","8% of men have colour vision deficiency"),
 ("6. Typography & print","No underlined rules text; all-caps limited to a handful of critical notes","Legibility"),
 ("6. Typography & print","Short sections do not break across pages; 2-page sections are on facing pages","Prevents mid-rule page turns"),
 ("6. Typography & print","Page count divisible by 4; spreads planned deliberately","Print reality"),
 ("7. Testing","At least one full blind playtest with people who have never seen the game","The only reliable detector of missing rules"),
 ("7. Testing","At least one blind test with non-gamers or non-native speakers","Experienced gamers paper over defects"),
 ("7. Testing","Testers were told not to use how-to-play videos","Not every owner will have internet access"),
 ("7. Testing","Designer did not intervene except to protect the rest of the test","Intervention destroys the data"),
 ("7. Testing","Timed look-up test on the pre-production copy: can a specific answer be found fast?","Slow look-up is a structural defect"),
 ("7. Testing","Rulebook read backwards, section by section, as a final QA pass","Prevents autopilot skimming"),
 ("8. Handover","A written style guide accompanies the text to the copyeditor and proofreader","Cheapest possible consistency insurance"),
 ("8. Handover","Editing done before layout; proofreading done after layout","Layout introduces its own errors"),
 ("8. Handover","Instructions to the graphic designer are unmistakably not rules text","Bracketed notes have shipped as rules before"),
 ("8. Handover","Rulebook version matches the component version being printed","Version drift is a classic defect source"),
 ("8. Handover","Searchable PDF and a public living-rules/errata page are planned","Ctrl-F is the index every game already ships with"),
]

